    const busy = manifest.map((m) => edits[m.gi]).filter(flying);
    if (busy.length) return { kind: "WAIT", kick: kickOf(busy) };
    return { kind: steps.FC_ABORT ? "ABORTED" : "REVIEW_DONE" };
